const memoryStores = new Map();
function getMemoryStore(storeKey) {
    const existing = memoryStores.get(storeKey);
    if (existing) {
        return existing;
    }
    const created = {
        nextId: 1,
        values: [],
    };
    memoryStores.set(storeKey, created);
    return created;
}
function supportsIndexedDb() {
    return typeof indexedDB !== "undefined";
}
function openDb(dbName, storeName) {
    return new Promise((resolve, reject) => {
        const request = indexedDB.open(dbName, 1);
        request.onerror = () => {
            reject(request.error ?? new Error(`Failed to open IndexedDB ${dbName}`));
        };
        request.onupgradeneeded = () => {
            const db = request.result;
            if (!db.objectStoreNames.contains(storeName)) {
                db.createObjectStore(storeName, {
                    autoIncrement: true,
                });
            }
        };
        request.onsuccess = () => {
            const db = request.result;
            if (!db.objectStoreNames.contains(storeName)) {
                db.close();
                reject(new Error(`Missing object store ${storeName}`));
                return;
            }
            resolve(db);
        };
    });
}
function withObjectStore(dbName, storeName, mode, run) {
    return openDb(dbName, storeName).then(async (db) => {
        try {
            const tx = db.transaction(storeName, mode);
            const store = tx.objectStore(storeName);
            const result = await run(store);
            await new Promise((resolve, reject) => {
                tx.oncomplete = () => resolve();
                tx.onerror = () => reject(tx.error ?? new Error("IndexedDB transaction failed"));
                tx.onabort = () => reject(tx.error ?? new Error("IndexedDB transaction aborted"));
            });
            return result;
        }
        finally {
            db.close();
        }
    });
}
function unwrapStoredValue(stored) {
    if (stored !== null &&
        typeof stored === "object" &&
        "value" in stored) {
        return stored.value;
    }
    return stored;
}
export function createPersistentQueue(options) {
    const { dbName, storeName } = options;
    const memoryKey = `${dbName}:${storeName}`;
    if (!supportsIndexedDb()) {
        return createMemoryQueue(memoryKey);
    }
    return {
        async add(value) {
            try {
                return await withObjectStore(dbName, storeName, "readwrite", (store) => {
                    return new Promise((resolve, reject) => {
                        const request = store.add({ value });
                        request.onerror = () => {
                            reject(request.error ?? new Error("IndexedDB add failed"));
                        };
                        request.onsuccess = () => {
                            resolve(Number(request.result));
                        };
                    });
                });
            }
            catch {
                return createMemoryQueue(memoryKey).add(value);
            }
        },
        async getAll(limit) {
            try {
                return await withObjectStore(dbName, storeName, "readonly", (store) => {
                    return new Promise((resolve, reject) => {
                        const rows = [];
                        const request = store.openCursor();
                        request.onerror = () => {
                            reject(request.error ?? new Error("IndexedDB cursor failed"));
                        };
                        request.onsuccess = () => {
                            const cursor = request.result;
                            if (!cursor) {
                                resolve(typeof limit === "number" ? rows.slice(0, limit) : rows);
                                return;
                            }
                            const id = Number(cursor.primaryKey);
                            if (!Number.isNaN(id)) {
                                rows.push({
                                    id,
                                    value: unwrapStoredValue(cursor.value),
                                });
                            }
                            if (typeof limit === "number" && rows.length >= limit) {
                                resolve(rows);
                                return;
                            }
                            cursor.continue();
                        };
                    });
                });
            }
            catch {
                return createMemoryQueue(memoryKey).getAll(limit);
            }
        },
        async deleteMany(ids) {
            if (ids.length === 0) {
                return;
            }
            try {
                await withObjectStore(dbName, storeName, "readwrite", (store) => {
                    return Promise.all(ids.map((id) => new Promise((resolve, reject) => {
                        const request = store.delete(id);
                        request.onerror = () => {
                            reject(request.error ?? new Error("IndexedDB delete failed"));
                        };
                        request.onsuccess = () => resolve();
                    }))).then(() => undefined);
                });
            }
            catch {
                await createMemoryQueue(memoryKey).deleteMany(ids);
            }
        },
        async count() {
            try {
                return await withObjectStore(dbName, storeName, "readonly", (store) => {
                    return new Promise((resolve, reject) => {
                        const request = store.count();
                        request.onerror = () => {
                            reject(request.error ?? new Error("IndexedDB count failed"));
                        };
                        request.onsuccess = () => resolve(request.result);
                    });
                });
            }
            catch {
                return createMemoryQueue(memoryKey).count();
            }
        },
    };
}
function createMemoryQueue(storeKey) {
    return {
        async add(value) {
            const store = getMemoryStore(storeKey);
            const id = store.nextId;
            store.nextId += 1;
            store.values.push({ id, value });
            return id;
        },
        async getAll(limit) {
            const store = getMemoryStore(storeKey);
            const rows = store.values.map((entry) => ({
                id: entry.id,
                value: entry.value,
            }));
            return typeof limit === "number" ? rows.slice(0, limit) : rows;
        },
        async deleteMany(ids) {
            const store = getMemoryStore(storeKey);
            const idSet = new Set(ids);
            store.values = store.values.filter((entry) => !idSet.has(entry.id));
        },
        async count() {
            const store = getMemoryStore(storeKey);
            return store.values.length;
        },
    };
}
